.alert {
  --_bg: var(--color-bg-subtle);
  --_border: var(--color-border-default);
  --_icon: var(--color-text-muted);

  box-sizing: border-box;
  display: flex;
  align-items: flex-start;
  gap: var(--space-3);
  padding: var(--space-3) var(--space-4);
  border: var(--border-width-default) solid var(--_border);
  border-radius: var(--alert-radius);
  background-color: var(--_bg);
  color: var(--color-text-default);
  font-family: var(--font-family-sans);
  font-size: var(--font-size-200);
  line-height: var(--font-line-height-normal);
}

.info {
  --_bg: var(--color-feedback-info-bg);
  --_border: var(--color-feedback-info-border);
  --_icon: var(--color-feedback-info-icon);
}

.success {
  --_bg: var(--color-feedback-success-bg);
  --_border: var(--color-feedback-success-border);
  --_icon: var(--color-feedback-success-icon);
}

.warning {
  --_bg: var(--color-feedback-warning-bg);
  --_border: var(--color-feedback-warning-border);
  --_icon: var(--color-feedback-warning-icon);
}

.danger {
  --_bg: var(--color-feedback-danger-bg);
  --_border: var(--color-feedback-danger-border);
  --_icon: var(--color-feedback-danger-icon);
}

/* The icon box matches one line of text so it stays aligned with the first line. */
.icon {
  height: calc(var(--font-size-200) * var(--font-line-height-normal));
  color: var(--_icon);
}

.content {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: var(--space-1);
  min-width: 0;
}

.title {
  margin: 0;
  font-weight: var(--font-weight-semibold);
}

.description {
  color: var(--color-text-default);
  max-width: 72ch;
}

.description > :where(p) {
  margin: 0;
}

.actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
  margin-block-start: var(--space-2);
}

/* actionsPlacement="inline": the actions end the message line and wrap under it when the line gets too narrow.
   Their negative block margin keeps a sm button inside the line box, so the text and the icon stay on one line. */
.inline .content {
  flex-flow: row wrap;
  align-items: center;
  gap: var(--space-3) var(--space-4);
}

.text {
  display: flex;
  flex: 1 1 24ch;
  flex-direction: column;
  gap: var(--space-1);
  min-width: 0;
}

.inline .actions {
  flex: none;
  margin-block: calc((var(--font-size-200) * var(--font-line-height-normal) - var(--control-height-sm)) / 2);
}

/* Pull the dismiss button into the padding so its glyph lines up with the text block. */
.dismiss {
  margin-block: calc(var(--space-1) * -1);
  margin-inline-end: calc(var(--space-2) * -1);
}

import type { Meta, StoryObj } from '@storybook/react-vite';
import { useState } from 'react';
import { SpecimenStack, Specimen } from '../../stories/StateGrid';
import { Button } from '../Button';
import { Link } from '../Link';
import { Alert, type AlertTone } from './Alert';

const meta = {
  title: 'Feedback/Alert',
  component: Alert,
  args: {
    tone: 'info',
    title: 'Figma sync is running',
    children: 'New variables appear here when the sync finishes. You can keep editing.',
  },
  argTypes: {
    tone: { control: 'inline-radio', options: ['neutral', 'info', 'success', 'warning', 'danger'] },
    icon: { control: false },
    actions: { control: false },
  },
  decorators: [(Story) => <div style={{ maxWidth: 640 }}><Story /></div>],
} satisfies Meta<typeof Alert>;

export default meta;
type Story = StoryObj<typeof meta>;

export const Info: Story = {};
export const Success: Story = { args: { tone: 'success', title: 'Tokens published', children: 'Version 1.4.0 is live. 12 tokens changed, 0 removed.' } };
export const Warning: Story = {
  args: { tone: 'warning', title: '3 tokens fail contrast', children: 'color.text.muted is below 4.5:1 on color.bg.subtle in the ocean brand.' },
};
export const Danger: Story = {
  args: {
    tone: 'danger',
    title: 'Publish failed',
    children: 'The token build found 2 broken aliases. Fix them and publish again.',
    actions: <Button size="sm" variant="secondary">View build log</Button>,
  },
};
export const Dismissible: Story = {
  render: (args) => {
    const [open, setOpen] = useState(true);
    return open ? (
      <Alert {...args} onDismiss={() => setOpen(false)} />
    ) : (
      <Button variant="secondary" onClick={() => setOpen(true)}>Show alert again</Button>
    );
  },
};

/** One short message with its action at the end of the line; under 390px the action wraps under the text. */
export const InlineAction: Story = {
  args: {
    tone: 'info',
    title: undefined,
    children: 'You are viewing change #12, not the latest library.',
    actionsPlacement: 'inline',
    actions: <Button size="sm" variant="secondary">Back to latest</Button>,
  },
