  overflow: hidden;
}

.padding-compact {
  --_inset: var(--space-3);
}

.padding-none {
  --_inset: 0;
}

.header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-3);
  padding: var(--_inset) var(--_inset) 0;
  font-family: var(--typography-h3-family);
  font-size: var(--typography-h3-size);
