.control {
  --_height: var(--control-height-md);
  --_px: var(--control-padding-x-md);

  box-sizing: border-box;
  display: flex;
  align-items: center;
  gap: var(--space-2);
  width: 100%;
  min-height: var(--_height);
  padding: 0 var(--_px);
  border: var(--border-width-default) solid var(--input-border);
  border-radius: var(--input-radius);
  background-color: var(--input-bg);
  color: var(--input-text);
  font-family: var(--font-family-sans);
  font-size: var(--font-size-200);
  cursor: text;
  transition-property: border-color, box-shadow, background-color;
  transition-duration: var(--motion-duration-instant);
  transition-timing-function: var(--motion-easing-standard);
}

.sm {
  --_height: var(--control-height-sm);
  --_px: var(--control-padding-x-sm);
}

.lg {
  --_height: var(--control-height-lg);

  font-size: var(--font-size-300);
}

@media (hover: hover) {
  .control:hover:not(:has(input[data-disabled], input[data-invalid], input[aria-invalid="true"])) {
    border-color: var(--input-border-hover);
