  height: var(--control-height-md);
  padding: 0 var(--table-cell-padding-x);
  border-bottom: var(--border-width-default) solid var(--color-border-default);
  background-color: var(--table-header-bg);
  color: var(--table-header-text);
  font-size: var(--font-size-100);
  font-weight: var(--font-weight-medium);
  letter-spacing: var(--font-tracking-wide);
  text-align: start;
  white-space: nowrap;
  vertical-align: middle;
}

.sticky .head {
  position: sticky;
  top: 0;
  z-index: 1;
}

.cell {
  height: var(--table-row-height);
  padding: 0 var(--table-cell-padding-x);
  border-bottom: var(--border-width-default) solid var(--table-border);
  vertical-align: middle;
}

.tbody .row:last-child .cell {
  border-bottom: 0;
}

.gridLines .cell + .cell,
.gridLines .head + .head {
  border-inline-start: var(--border-width-default) solid var(--table-border);
}

/* Column widths (width and minWidth props). Unset, both fall back to auto. */
.head,
.cell {
  width: var(--_col-width);
  min-width: var(--_col-min-width);
}

.numeric {
  text-align: end;
  font-variant-numeric: tabular-nums;
}

.numeric .sortButton {
  flex-direction: row-reverse;
}

.select {
  width: var(--size-6);
  padding-inline-end: 0;
}

/* The selection checkbox's label is visually hidden: drop its gap. */
.select :where(label) {
  gap: 0;
}

.row {
  transition-property: background-color;
  transition-duration: var(--motion-duration-instant);
  transition-timing-function: var(--motion-easing-standard);
}

@media (hover: hover) {
  .tbody .row:hover {
    background-color: var(--table-row-bg-hover);
  }
}

.row[data-selected] {
  background-color: var(--table-row-bg-selected);
}

/* Sortable header: the whole label is the button, the icon shows the current direction. */
.sortButton {
  display: inline-flex;
  align-items: center;
  gap: var(--space-1);
  margin: 0 calc(var(--space-1) * -1);
  padding: var(--space-1);
  border: 0;
  border-radius: var(--radius-inset);
  background-color: transparent;
  color: inherit;
  font: inherit;
  letter-spacing: inherit;
  cursor: pointer;
}

@media (hover: hover) {
  .sortButton:hover {
    color: var(--color-text-default);
  }
}

.sortButton:focus-visible {
  outline: var(--focus-ring-width) solid var(--focus-ring-color);
  outline-offset: 0;
}

.sortButton[data-sorted] {
  color: var(--color-text-default);
}

.sortIcon {
  opacity: 0.6;
}

.sortButton[data-sorted] .sortIcon {
  color: var(--color-signal-default);
  opacity: 1;
}

.empty {
  padding: var(--space-8) var(--table-cell-padding-x);
  color: var(--color-text-muted);
  text-align: center;
}

/* narrowLayout="stack": in a container under 30em (480px), each row becomes a card and every value sits beside its
   column name (data-label, filled from the header row). The scroller is the size container. */
.stack {
  container-type: inline-size;
}

@container (max-width: 30em) {
  .stack .table,
  .stack .tbody,
  .stack .row {
    display: block;
  }

  .stack .thead {
    display: none;
  }

  .stack .caption {
    display: block;
  }

  /* Records are cards: a full-strength divider between them, stronger than the hairline between desktop rows. */
  .stack .tbody .row {
    padding-block: var(--space-2);
    border-bottom: var(--border-width-default) solid var(--color-border-default);
  }

  .stack .tbody .row:last-child {
    border-bottom: 0;
  }

  /* Two columns: the column name (muted, 40%) beside its value. The name is positioned, so the value keeps its own
     flow (inline markup, wrapping text, a badge) and every wrapped line stays in the value column. */
  .stack .cell {
    position: relative;
    display: block;
    width: auto;
    min-width: 0;
    height: auto;
    padding-block: var(--space-1);
    padding-inline-start: calc(40% + var(--space-3));
    border: 0;
    text-align: start;
  }

  .stack .cell::before {
    content: attr(data-label);
    position: absolute;
    inset-inline-start: var(--table-cell-padding-x);
    width: calc(40% - var(--table-cell-padding-x));
    overflow: hidden;
    color: var(--table-header-text);
    font-size: var(--font-size-100);
    font-weight: var(--font-weight-medium);
    letter-spacing: var(--font-tracking-wide);
    line-height: var(--font-line-height-normal);
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  /* No column name (a title cell, the empty row): the value alone, full width, as the card's heading. */
  .stack .cell:is(:not([data-label]), [data-label=""]) {
    padding-inline-start: var(--table-cell-padding-x);
    font-weight: var(--font-weight-medium);
  }

  .stack .cell:is(:not([data-label]), [data-label=""])::before {
    content: none;
  }

  .stack .gridLines .cell + .cell {
    border-inline-start: 0;
  }

  .stack .empty {
    display: block;
  }
}

